const raw = $json.content[0].text;
const cleaned = raw.replace(/^```json\s*/m, '').replace(/```\s*$/m, '').trim();
const d = JSON.parse(cleaned);

const G = x => Math.round(x * 914400);

const MG = 0.50;
const CW = 9.00;

const Y_TR  = 0.28;
const Y_EYE = 0.36;
const EYE_H = 0.15;
const Y_HL  = 0.56;
const HL_H  = 0.44;
const Y_SH  = 1.06;
const SH_H  = 0.26;
const Y_MR  = 1.40;
const Y_CON = 1.56;
const Y_BR  = 4.95;
const CON_H = Y_BR - Y_CON;
const Y_TAG = 5.04;
const TAG_H = 0.18;
const Y_FOOT = 5.28;
const FOOT_H = 0.18;

const BG  = {red:0.980, green:0.984, blue:0.965};
const INK = {red:0.055, green:0.055, blue:0.047};
const ACC = {red:0.800, green:0.051, blue:0.173};
const MUT = {red:0.541, green:0.541, blue:0.525};
const RUL = {red:0.851, green:0.851, blue:0.824};
const WHT = {red:1, green:1, blue:1};

let _n = 0;
const uid = p => `nvg_${p}_${++_n}`;
let _page = '';

function mkTBox(id, x, y, w, h) {
  return { createShape: {
    objectId: id, shapeType: 'TEXT_BOX',
    elementProperties: {
      pageObjectId: _page,
      size: { width:{magnitude:G(w),unit:'EMU'}, height:{magnitude:G(h),unit:'EMU'} },
      transform: { scaleX:1, scaleY:1, translateX:G(x), translateY:G(y), unit:'EMU' }
    }
  }};
}

function mkRect(id, x, y, w, h) {
  return { createShape: {
    objectId: id, shapeType: 'RECTANGLE',
    elementProperties: {
      pageObjectId: _page,
      size: { width:{magnitude:G(w),unit:'EMU'}, height:{magnitude:G(h),unit:'EMU'} },
      transform: { scaleX:1, scaleY:1, translateX:G(x), translateY:G(y), unit:'EMU' }
    }
  }};
}

function transparent(id) {
  return { updateShapeProperties: {
    objectId: id, fields: 'shapeBackgroundFill,outline',
    shapeProperties: {
      shapeBackgroundFill: { propertyState: 'NOT_RENDERED' },
      outline: { propertyState: 'NOT_RENDERED' }
    }
  }};
}

function solidFill(id, fillRgb, lineRgb, lineEmu) {
  const sp = { shapeBackgroundFill: { solidFill: { color: { rgbColor: fillRgb } } } };
  sp.outline = lineRgb
    ? { outlineFill: { solidFill: { color: { rgbColor: lineRgb } } }, weight: {magnitude: lineEmu||2000, unit:'EMU'} }
    : { propertyState: 'NOT_RENDERED' };
  return { updateShapeProperties: {
    objectId: id, fields: 'shapeBackgroundFill,outline',
    shapeProperties: sp
  }};
}

function valignMiddle(id) {
  return { updateShapeProperties: {
    objectId: id, fields: 'contentAlignment',
    shapeProperties: { contentAlignment: 'MIDDLE' }
  }};
}

function insText(id, text) {
  return { insertText: { objectId: id, insertionIndex: 0, text } };
}

function txStyle(id, rgb, pt, bold, italic, font, si, ei) {
  const range = (si !== undefined && ei !== undefined)
    ? { type: 'FIXED_RANGE', startIndex: si, endIndex: ei }
    : { type: 'ALL' };
  return { updateTextStyle: {
    objectId: id, textRange: range,
    fields: 'foregroundColor,fontSize,bold,italic,fontFamily',
    style: {
      foregroundColor: { opaqueColor: { rgbColor: rgb } },
      fontSize: { magnitude: pt, unit: 'PT' },
      bold: !!bold, italic: !!italic,
      fontFamily: font || 'Inter'
    }
  }};
}

function paraStyle(id, align) {
  return { updateParagraphStyle: {
    objectId: id, textRange: { type: 'ALL' },
    fields: 'alignment,spaceAbove,spaceBelow',
    style: { alignment: align || 'START',
             spaceAbove: {magnitude:0,unit:'PT'},
             spaceBelow: {magnitude:0,unit:'PT'} }
  }};
}

function setBg(pageId) {
  return { updatePageProperties: {
    objectId: pageId, fields: 'pageBackgroundFill',
    pageProperties: { pageBackgroundFill: { solidFill: { color: { rgbColor: BG } } } }
  }};
}

function addText(x, y, w, h, text, rgb, pt, bold, italic, font, align) {
  const id = uid('t');
  return [mkTBox(id, x, y, w, h), transparent(id), insText(id, text),
          txStyle(id, rgb, pt, bold, italic, font), paraStyle(id, align || 'START')];
}

function hRule(y) {
  const id = uid('hr');
  return [mkRect(id, MG, y, CW, 0.004), solidFill(id, RUL, null)];
}
function tRule(y) {
  const id = uid('tr');
  return [mkRect(id, MG, y, CW, 0.002), solidFill(id, RUL, null)];
}

function slideHeader(eyebrow, headline, hlPt, subhead) {
  const r = [];
  r.push(...hRule(Y_TR));
  r.push(...addText(MG, Y_EYE, CW, EYE_H, eyebrow.toUpperCase(), MUT, 10, true, false, 'Inter', 'START'));
  r.push(...addText(MG, Y_HL,  CW, HL_H,  headline,              INK, hlPt, true, false, 'Inter', 'START'));
  r.push(...addText(MG, Y_SH,  CW, SH_H,  subhead,               ACC, 13, true, true, 'Georgia', 'START'));
  r.push(...hRule(Y_MR));
  return r;
}

function footerRow(pg, total) {
  const r = [];
  const wmId = uid('wm');
  r.push(mkTBox(wmId, MG, Y_FOOT, 2.0, FOOT_H));
  r.push(transparent(wmId));
  r.push(insText(wmId, 'novagentica'));
  r.push(txStyle(wmId, INK, 11, true, false, 'Inter', 0, 4));
  r.push(txStyle(wmId, ACC, 11, true, false, 'Inter', 4, 11));
  r.push(paraStyle(wmId, 'START'));

  const pnId = uid('pn');
  const pStr = String(pg).padStart(2,'0') + ' / ' + String(total).padStart(2,'0');
  r.push(mkTBox(pnId, MG + CW - 1.2, Y_FOOT, 1.2, FOOT_H));
  r.push(transparent(pnId));
  r.push(insText(pnId, pStr));
  r.push(txStyle(pnId, MUT, 10, false, false, 'Inter'));
  r.push(paraStyle(pnId, 'END'));
  return r;
}

const reqs = [];
const TOTAL = 3;
const PG1 = 'slide_opp', PG2 = 'slide_agt', PG3 = 'slide_eco';

// SLIDE 1
reqs.push({ createSlide: { objectId: PG1, insertionIndex: 0,
  slideLayoutReference: { predefinedLayout: 'BLANK' } } });
reqs.push(setBg(PG1));
_page = PG1;
reqs.push(...slideHeader(d.slide1.eyebrow, d.slide1.headline, 22, d.slide1.subhead));

const rows = d.slide1.rows;
const ROW_H   = (CON_H - 0.12) / rows.length;
const ROW_GAP = 0.06;
const LBL_W   = 1.55;
const BODY_X  = MG + LBL_W + 0.14;
const BODY_W  = CW - LBL_W - 0.14;

rows.forEach((row, i) => {
  const ry = Y_CON + i * ROW_H;
  reqs.push(...addText(MG, ry + 0.06, LBL_W, ROW_H - 0.06,
    row.label.toUpperCase(), MUT, 10, true, false, 'Inter', 'START'));

  const bodyFull = row.body + (row.italic ? '\n' + row.italic : '');
  const bId = uid('rb');
  reqs.push(mkTBox(bId, BODY_X, ry + 0.05, BODY_W, ROW_H - ROW_GAP));
  reqs.push(transparent(bId));
  reqs.push(insText(bId, bodyFull));
  reqs.push(txStyle(bId, INK, 11, false, false, 'Georgia', 0, row.body.length));
  if (row.italic) {
    reqs.push(txStyle(bId, ACC, 11, true, true, 'Georgia', row.body.length + 1, bodyFull.length));
  }
  reqs.push(paraStyle(bId, 'START'));

  if (i < rows.length - 1) reqs.push(...tRule(ry + ROW_H - ROW_GAP / 2));
});

reqs.push(...hRule(Y_BR));
reqs.push(...addText(MG, Y_TAG, CW, TAG_H, d.slide1.tagline, MUT, 11, false, true, 'Georgia', 'START'));
reqs.push(...footerRow(1, TOTAL));

// SLIDE 2
reqs.push({ createSlide: { objectId: PG2, insertionIndex: 1,
  slideLayoutReference: { predefinedLayout: 'BLANK' } } });
reqs.push(setBg(PG2));
_page = PG2;
reqs.push(...slideHeader(d.slide2.eyebrow, d.slide2.headline, 26, d.slide2.subhead));

const tiles = d.slide2.tiles;
const N    = tiles.length;
const TGAP = 0.10;
const TW   = (CW - TGAP * (N - 1)) / N;
const TH   = CON_H - 0.05;
const TPAD = 0.12;
const BADGE = 0.32;

tiles.forEach((tile, i) => {
  const tx = MG + i * (TW + TGAP);
  const ty = Y_CON;

  const tileId = uid('tile');
  reqs.push(mkRect(tileId, tx, ty, TW, TH));
  reqs.push(solidFill(tileId, BG, RUL, 2000));

  const badgeId = uid('bdg');
  reqs.push(mkRect(badgeId, tx + TPAD, ty + TPAD, BADGE, BADGE));
  reqs.push(solidFill(badgeId, ACC, null));

  const numId = uid('bnum');
  reqs.push(mkTBox(numId, tx + TPAD, ty + TPAD, BADGE, BADGE));
  reqs.push(transparent(numId));
  reqs.push(valignMiddle(numId));
  reqs.push(insText(numId, tile.num));
  reqs.push(txStyle(numId, WHT, 14, true, false, 'Inter'));
  reqs.push(paraStyle(numId, 'CENTER'));

  const titleY = ty + TPAD + BADGE + 0.10;
  reqs.push(...addText(tx + TPAD, titleY, TW - TPAD, 0.22,
    tile.title.toUpperCase(), INK, 10, true, false, 'Inter', 'START'));

  const bodyY = titleY + 0.52;
  const bodyH = TH - (bodyY - ty) - 0.10;
  reqs.push(...addText(tx + TPAD, bodyY, TW - TPAD, bodyH,
    tile.body, INK, 11, false, false, 'Georgia', 'START'));
});

reqs.push(...hRule(Y_BR));
reqs.push(...addText(MG, Y_TAG, CW, TAG_H, d.slide2.tagline, MUT, 11, false, true, 'Georgia', 'START'));
reqs.push(...footerRow(2, TOTAL));

// SLIDE 3
reqs.push({ createSlide: { objectId: PG3, insertionIndex: 2,
  slideLayoutReference: { predefinedLayout: 'BLANK' } } });
reqs.push(setBg(PG3));
_page = PG3;
reqs.push(...slideHeader(d.slide3.eyebrow, d.slide3.headline, 26, d.slide3.subhead));

const stacks = d.slide3.stacks;
const SH   = (CON_H - 0.10) / stacks.length;
const NUMW = 0.70;
const LX   = MG + NUMW + 0.12;
const LW   = CW - NUMW - 0.12;

stacks.forEach((row, i) => {
  const sy = Y_CON + i * SH;
  const nc = row.highlight ? ACC : MUT;

  const nId = uid('sn');
  reqs.push(mkTBox(nId, MG, sy, NUMW, SH));
  reqs.push(transparent(nId));
  reqs.push(valignMiddle(nId));
  reqs.push(insText(nId, row.num));
  reqs.push(txStyle(nId, nc, 20, true, false, 'Inter'));
  reqs.push(paraStyle(nId, 'START'));

  reqs.push(...addText(LX, sy + 0.07, LW, 0.22,
    row.label.toUpperCase(), INK, 10, true, false, 'Inter', 'START'));

  reqs.push(...addText(LX, sy + 0.32, LW, SH - 0.38,
    row.text, INK, 11, false, false, 'Georgia', 'START'));

  if (i < stacks.length - 1) reqs.push(...tRule(sy + SH - 0.02));
});

reqs.push(...hRule(Y_BR));
reqs.push(...addText(MG, Y_TAG, CW, TAG_H, d.slide3.tagline, MUT, 11, false, true, 'Georgia', 'START'));
reqs.push(...footerRow(3, TOTAL));

const vertical = d.vertical || d.slide1.eyebrow.split('·')[0].replace(/\s+/g, ' ').trim();
const title = d.title || d.slide1.headline;
return { requests: reqs, title: vertical + ' — ' + title, vertical };

// Defensive parse: a malformed Claude response must not halt the batch.
try {
  const raw = $json.content[0].text;
  const cleaned = raw.replace(/^```json\s*/m, '').replace(/```\s*$/m, '').trim();
  JSON.parse(cleaned);
  return $input.item; // valid JSON -> pass the original item through unchanged
} catch (err) {
  let pageId = null, useCase = null;
  try {
    const fp = $('Fetch Use Case Page').item.json;
    pageId = fp.id || null;
    useCase = fp.name || fp.property_use_case || null;
  } catch (e) {}
  const snippet = (($json.content && $json.content[0] && $json.content[0].text) || '').slice(0, 600);
  return { json: { _parseError: true, errorMsg: err.message, useCase: useCase, pageId: pageId, snippet: snippet } };
}

